/// Body of a system registered with `sturdy_ecs_add_chunk_system_ex` (since 0.35): called once per matching archetype with that archetype's contiguous arrays, instead of once per entity.
///
/// `entities` holds `count` entities. `columns[i]` is the first element of an array of `count` components, one array per entry of the access list in the order it was given, each element as large as that component's size; element `r` of every array belongs to `entities[r]`. Write through the arrays declared `STURDY_ACCESS_WRITE`. All pointers are valid only for this call. `commands` is as for `SturdySystemFn`.
///
/// One call crosses the language boundary for a whole archetype, so a system over 10,000 entities costs a few calls instead of 10,000: use this for anything per-frame over many entities.
pub type SturdyChunkSystemFn = unsafe extern "C" fn(*const SturdyEntity, u32, *mut *mut c_void, SturdyCommands, *mut c_void);

/// Receives one matching entity during `sturdy_ecs_for_each`.
///
/// `components` points at an array parallel to the component ids you asked to match, each entry addressing that component's storage for this entity. Write through them to mutate in place. The pointers are valid only for the duration of this call.
///
/// While a visit is in progress the world is locked, so this callback must **not** call any other `sturdy_ecs_*` function; each returns `STURDY_ERROR_BUSY`. That guard is doing real work — the engine underneath treats a structural change made during iteration as a fatal contract violation, so without it a reentrant spawn would terminate the process rather than fail. Read and write through `components`; if you need to spawn or destroy, record what you want and do it after `sturdy_ecs_for_each` returns.
pub type SturdyEcsVisitFn = unsafe extern "C" fn(SturdyEntity, *mut *mut c_void, *mut c_void);

/// Invoked once per log message after registration via `sturdy_log_add_sink`.
pub type SturdyLogCallback = unsafe extern "C" fn(i32, *const c_char, u64, *mut c_void);

/// The one function a plugin exports, under the name `sturdy_plugin_entry`. Return `STURDY_OK` to accept the load; anything else aborts it, destroys any modules already added, and `UNLOAD` is *not* called. For `UNLOAD`, `host->context` is valid but `add_module` is refused, and `state` carries what the plugin stored.
pub type SturdyPluginEntryFn = unsafe extern "C" fn(*const SturdyPluginHost, i32, *mut c_void) -> i32;

pub type SturdyReflectionCopyConstructFn = unsafe extern "C" fn(*mut c_void, *const c_void, *mut c_void);

pub type SturdyReflectionDefaultConstructFn = unsafe extern "C" fn(*mut c_void, *mut c_void);

pub type SturdyReflectionDestroyFn = unsafe extern "C" fn(*mut c_void, *mut c_void);

/// Same shape as `SturdyReflectionMethodFn`'s two data-access halves — a non-`Trivial` field's copy-out implementation, called with `object` = the field-owning instance.
pub type SturdyReflectionFieldGetFn = unsafe extern "C" fn(*const c_void, *mut c_void);

/// Copy-in counterpart to `SturdyReflectionFieldGetFn`.
pub type SturdyReflectionFieldSetFn = unsafe extern "C" fn(*mut c_void, *const c_void);

/// A type-erased method call/override/hook body: `object` is the receiver (null for a static method), `args` is one already-typed, caller-marshalled pointer per parameter (see `SturdyReflectionMethodInfo::param_count`), `out_return` is uninitialized storage for the return value (ignored when the method returns nothing), `user_data` is whatever was passed to `sturdy_reflection_register_override`.
pub type SturdyReflectionMethodFn = unsafe extern "C" fn(*mut c_void, *const *const c_void, *mut c_void, *mut c_void);

/// Sets the construct/destroy callbacks for the type being built.
pub type SturdyReflectionMoveConstructFn = unsafe extern "C" fn(*mut c_void, *mut c_void, *mut c_void);

/// A type-erased *observer* body — used for both a method before/after hook and an event listener, which share this exact shape (unlike `SturdyReflectionMethodFn`, there is no `out_return`: neither a hook nor an event listener produces a value, only observes `args`). `object` is the method's receiver (null for a static method) or whatever `sturdy_reflection_fire_event` was called with; `args` is one already-typed pointer per parameter; `user_data` is whatever was passed to `_add_before_hook`/`_add_after_hook`/ `_subscribe_event`.
pub type SturdyReflectionObserverFn = unsafe extern "C" fn(*mut c_void, *const *const c_void, *mut c_void);

/// Body of a system registered with `sturdy_ecs_add_system`.
///
/// `components` points at an array parallel to the access list the system was registered with, each entry addressing that component's storage for this entity. Write through the ones declared `STURDY_ACCESS_WRITE`; the pointers are valid only for this call.
///
/// `commands` queues spawns, destroys and component changes for the engine to apply once the stage finishes. That indirection is not optional — the world cannot be restructured while systems are reading it, which is why the direct `sturdy_ecs_spawn` family reports `STURDY_ERROR_BUSY` here.
pub type SturdySystemFn = unsafe extern "C" fn(SturdyEntity, *mut *mut c_void, SturdyCommands, *mut c_void);

/// Body of a background task.
///
/// Runs on a scheduler worker thread, not the thread that spawned it. Must not unwind.
///
/// Nothing in this ABI is safe to call concurrently with the engine's own frame from a worker thread — the ECS and renderer entry points assume the caller is the thread the engine handed a handle to. Use tasks for work that does not touch the engine (loading, decoding, pathfinding, network), publish the result somewhere your game logic reads, and apply it from a system or frame callback.
pub type SturdyTaskFn = unsafe extern "C" fn(*mut c_void);

