/// Opaque by value: the bytes are the engine's own asset handle, copied in and out rather than interpreted. Copy it freely, compare it with `memcmp`, and treat a zeroed value as invalid. It stays valid for as long as the engine that produced it.
#[repr(C)]
#[derive(Clone, Copy)]
pub struct SturdyAsset {
    pub opaque: [u64; 4],
}
impl Default for SturdyAsset {
    /// All zero: null pointers, absent callbacks, zero numbers. Set `struct_size` where the struct has one.
    fn default() -> Self {
        unsafe { core::mem::zeroed() }
    }
}
const _: () = assert!(core::mem::size_of::<SturdyAsset>() == 32 && core::mem::align_of::<SturdyAsset>() == 8);
const _: () = assert!(core::mem::offset_of!(SturdyAsset, opaque) == 0);

