    /// Replays `bundles` into `pass`, which must have been created with `SturdyRenderPassDesc::allow_bundles` set.
    pub fn sturdy_rhi_render_pass_execute_bundles(pass: SturdyRenderPassEncoder, bundle_count: u32, bundles: *const SturdyRenderBundle) -> i32;
