    /// Sets the pipeline used by subsequent draws.
    pub fn sturdy_rhi_render_pass_set_pipeline(pass: SturdyRenderPassEncoder, pipeline: SturdyRenderPipeline) -> i32;
    /// Writes push-constant bytes visible to `stages`.
    pub fn sturdy_rhi_render_pass_set_push_constants(pass: SturdyRenderPassEncoder, stages: u32, offset: u32, data: *const c_void, data_size: u64) -> i32;
    pub fn sturdy_rhi_render_pass_set_scissor(pass: SturdyRenderPassEncoder, scissor: *const SturdyRect2D) -> i32;
    pub fn sturdy_rhi_render_pass_set_stencil_reference(pass: SturdyRenderPassEncoder, reference: u32) -> i32;
    /// Binds a vertex buffer at `slot`, matching the pipeline's `vertex_buffers` layout array index.
    pub fn sturdy_rhi_render_pass_set_vertex_buffer(pass: SturdyRenderPassEncoder, slot: u32, buffer: SturdyBuffer, offset: u64) -> i32;
    pub fn sturdy_rhi_render_pass_set_viewport(pass: SturdyRenderPassEncoder, viewport: *const SturdyViewport) -> i32;
    /// Fills `desc` with `struct_size` and engine defaults (triangle list, fill/back-cull/CCW rasterization, no multisampling, no depth/stencil, no color targets, zeroed shader entries).
    pub fn sturdy_rhi_render_pipeline_desc_init(desc: *mut SturdyRenderPipelineDesc) -> i32;
    /// Resets one or more fences to unsignaled.
    pub fn sturdy_rhi_reset_fences(engine: SturdyEngine, fence_count: u32, fences: *const SturdyFence) -> i32;
    /// Resets `count` queries starting at `first` to the unavailable state, outside any command encoder. Every query must be reset (via this or `sturdy_rhi_command_encoder_reset_query_set`) before its first use.
    pub fn sturdy_rhi_reset_query_set(engine: SturdyEngine, query_set: SturdyQuerySet, first: u32, count: u32) -> i32;
    /// Fills `desc` with `struct_size` and engine defaults (linear filtering/mipmapping, repeat addressing, LOD range [0, 1000], no anisotropy, no comparison).
    pub fn sturdy_rhi_sampler_desc_init(desc: *mut SturdySamplerDesc) -> i32;
    /// Reads the semaphore's current counter value.
    pub fn sturdy_rhi_semaphore_value(engine: SturdyEngine, semaphore: SturdySemaphore, out_value: *mut u64) -> i32;
    /// Advances `semaphore`'s counter to `value` from the host. Rarely needed directly — a submission with a signal entry (see `sturdy_rhi_submit`) is the usual way a semaphore advances.
    pub fn sturdy_rhi_signal_semaphore(engine: SturdyEngine, semaphore: SturdySemaphore, value: u64) -> i32;
    /// Submits finished command buffers to a device queue for execution.
    pub fn sturdy_rhi_submit(engine: SturdyEngine, queue_class: i32, queue_lane_index: u32, command_buffer_count: u32, command_buffers: *const SturdyCommandBuffer, wait_count: u32, waits: *const SturdySemaphoreWait, signal_count: u32, signals: *const SturdySemaphoreSignal, fence: SturdyFence, one_shot: u8) -> i32;
    /// Fills `desc` with `struct_size` and engine defaults (2D, `STURDY_FORMAT_UNDEFINED`, 1x1x1, one mip level, one sample, no usage flags).
    pub fn sturdy_rhi_texture_desc_init(desc: *mut SturdyTextureDesc) -> i32;
    /// Unmaps a buffer previously mapped with `sturdy_rhi_map_buffer`.
    pub fn sturdy_rhi_unmap_buffer(engine: SturdyEngine, buffer: SturdyBuffer) -> i32;
    /// Waits for one or more fences to become signaled — the correct way to know a specific submission has finished. Prefer this over `sturdy_rhi_wait_idle`, which is a device-wide barrier and unsafe to interleave with any other GPU work in flight, including the engine's own.
    pub fn sturdy_rhi_wait_fences(engine: SturdyEngine, fence_count: u32, fences: *const SturdyFence, wait_all: u8, timeout_ns: u64, out_signaled: *mut u8) -> i32;
    /// Blocks until every queue on the active device has finished all submitted work. Expensive, and unsafe to call while any other GPU work — including the engine's own internal one-shot uploads — may still be in flight on this device. Intended for shutdown/resource-teardown synchronization; wait on a specific submission with `sturdy_rhi_wait_fences` instead.
    pub fn sturdy_rhi_wait_idle(engine: SturdyEngine) -> i32;
    /// Blocks the calling host thread until `semaphore`'s counter reaches `value`.
    pub fn sturdy_rhi_wait_semaphore(engine: SturdyEngine, semaphore: SturdySemaphore, value: u64, timeout_ns: u64) -> i32;
    /// Uploads `data` into `buffer` at `offset`, outside any command encoder. Suitable for infrequent, host-visible writes; for per-frame or GPU-timed writes use `sturdy_rhi_command_encoder_update_buffer` instead.
    pub fn sturdy_rhi_write_buffer(engine: SturdyEngine, buffer: SturdyBuffer, offset: u64, data: *const c_void, data_size: u64) -> i32;
    /// Reads `group_count` shader group handles starting at `first_group`, into `dst` (which must be at least `group_count * sturdy_rhi_ray_tracing_properties`'s `shader_group_handle_size` bytes). Write these into a shader binding table buffer at `shader_group_base_alignment`-aligned offsets to build `SturdyShaderBindingTableRegion`s for `sturdy_rhi_command_encoder_trace_rays`.
    pub fn sturdy_rhi_write_ray_tracing_shader_group_handles(engine: SturdyEngine, pipeline: SturdyRayTracingPipeline, first_group: u32, group_count: u32, dst: *mut c_void, dst_size: u64) -> i32;
    /// Fills `config` with engine defaults and the correct `struct_size`.
    ///
    /// Always call this before setting fields. It is what makes a binding compiled against an older header keep working against a newer engine: fields you have never heard of still get sane values instead of whatever was on your stack.
    pub fn sturdy_runtime_config_init(config: *mut SturdyRuntimeConfig) -> i32;
    /// Runs the application to completion: creates the window and graphics device, drives the frame loop, and returns once the last window closes.
    ///
    /// Blocks the calling thread for the entire lifetime of the application. Only one runtime may be active per process; a concurrent or nested call fails with `STURDY_ERROR_ALREADY_RUNNING` rather than corrupting the first one's state.
    pub fn sturdy_runtime_run(config: *const SturdyRuntimeConfig, game_logic: *const SturdyGameLogic, argc: i32, argv: *const *const c_char, out_exit_code: *mut i32) -> i32;
    /// Like `sturdy_runtime_run`, for a game made of several modules (since 0.35).
    ///
    /// Modules start in the order you list them, adjusted so each comes after the modules in its `after` list; they shut down in the reverse order. If a module's `on_engine_initialized` returns false (or a dependency is unknown or cyclic), every module that had started is shut down and the call returns `STURDY_ERROR_CALLBACK_FAILED` (or `STURDY_ERROR_INITIALIZATION_FAILED` for a bad dependency, with the cause in the engine log).
    ///
    /// For each frame every module's `request_render_frame` runs in start order. Among modules with `contributes_scene`, the last one that returns true supplies the camera, lighting and render graph; every module's overlay passes are kept, in start order. If no scene module returns true the frame is skipped.
    ///
    /// Threading is as for `sturdy_runtime_run`: `request_render_frame` may run on per-window render threads, so a module's own state must be safe for that. The module list never changes after startup.
    pub fn sturdy_runtime_run_modules(config: *const SturdyRuntimeConfig, modules: *const SturdyGameModule, module_count: u32, argc: i32, argv: *const *const c_char, out_exit_code: *mut i32) -> i32;
    /// Returns how many animation clips the imported scene carries.
    pub fn sturdy_scene_clip_count(scene: SturdyGltfScene, out_count: *mut u32) -> i32;
    /// Reads the length of clip `index` in seconds.
    pub fn sturdy_scene_clip_duration(scene: SturdyGltfScene, index: u32, out_seconds: *mut f32) -> i32;
    /// Reads the name of clip `index`. See the string-output convention above.
    pub fn sturdy_scene_clip_name(scene: SturdyGltfScene, index: u32, buffer: *mut c_char, capacity: u64, out_length: *mut u64) -> i32;
    /// Fills `settings` with `struct_size` and engine defaults (raster deferred, path tracing parameters set but unused until `integrator` selects a path-traced mode).
    pub fn sturdy_scene_settings_init(settings: *mut SturdySceneSettings) -> i32;
    /// Spawns every model and light of the scene with its animation wired up: skinned characters get a private deformable copy and an animator, blend-shape meshes likewise, and plain animated nodes follow the file's node animation. `sturdy_gltf_spawn_all` is this with default options.
    pub fn sturdy_scene_spawn(engine: SturdyEngine, scene: SturdyGltfScene, options: *const SturdySpawnOptions, out_entities: *mut SturdyEntity, capacity: u32, out_count: *mut u32) -> i32;
    /// Fills `settings` with `struct_size` and engine defaults (disabled).
    pub fn sturdy_screen_space_gi_settings_init(settings: *mut SturdyScreenSpaceGiSettings) -> i32;
    /// Fills `settings` with `struct_size` and engine defaults (4 cascades, 4096 atlas, contact shadows on, contact hardening off).
    pub fn sturdy_shadow_settings_init(settings: *mut SturdyShadowSettings) -> i32;
    /// Decodes a file (any supported codec; cached by path) without playing it.
    pub fn sturdy_sound_load(engine: SturdyEngine, path: *const c_char, out_sound: *mut SturdySound) -> i32;
    /// Plays a loaded sound. `out_voice` may be null for fire-and-forget; a returned voice must still be released.
    pub fn sturdy_sound_play(engine: SturdyEngine, sound: SturdySound, options: *const SturdyPlayOptions, out_voice: *mut SturdyVoice) -> i32;
    pub fn sturdy_sound_release(sound: SturdySound) -> i32;
    /// Fills `options` with the defaults: auto-play, looping, speed 1, first clip, identity transform.
    pub fn sturdy_spawn_options_init(options: *mut SturdySpawnOptions) -> i32;
    /// Reads what `surface`'s presentation policy actually resolved to.
    pub fn sturdy_surface_presentation_resolution(engine: SturdyEngine, surface: SturdySurface, out_resolution: *mut SturdyPresentationResolution) -> i32;
    /// Reads `surface`'s current presentation policy: the last value `sturdy_surface_set_presentation_settings` accepted, or the app-wide default if never overridden.
    pub fn sturdy_surface_presentation_settings(engine: SturdyEngine, surface: SturdySurface, out_settings: *mut SturdyPresentationSettings) -> i32;
    /// Queries `surface`'s real HDR display capabilities and supported presentation modes.
    pub fn sturdy_surface_query_hdr_capabilities(engine: SturdyEngine, surface: SturdySurface, out_capabilities: *mut SturdyHdrCapabilities, out_modes: *mut SturdyHdrPresentationMode, modes_capacity: u32, out_mode_count: *mut u32) -> i32;
    /// Requests a change to `surface`'s presentation policy. Queued like a window request: applied the next time `surface` renders, not synchronously.
    pub fn sturdy_surface_set_presentation_settings(engine: SturdyEngine, surface: SturdySurface, settings: *const SturdyPresentationSettings) -> i32;
