    /// Reads the time step for the current tick, after the time scale is applied.
    ///
    /// This is the value gameplay should integrate against. It differs from `SturdyFrameInput`'s `delta_seconds`, which is raw per-surface frame time and ignores the scale entirely.
    pub fn sturdy_time_delta_seconds(engine: SturdyEngine, out_seconds: *mut f64) -> i32;
    /// Reads the current time scale. 1.0 is real time, 0.0 is fully paused.
    pub fn sturdy_time_scale(engine: SturdyEngine, out_scale: *mut f64) -> i32;
    /// Sets the time scale.
    pub fn sturdy_time_set_scale(engine: SturdyEngine, scale: f64) -> i32;
    /// Reads the monotonically increasing simulation tick counter.
    pub fn sturdy_time_tick_index(engine: SturdyEngine, out_tick_index: *mut u64) -> i32;
    /// Reads the time step for the current tick before the time scale is applied.
